from pathlib import Path
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.lib import colors
root=Path('/workspace/demo-setup/pdfs');root.mkdir(exist_ok=True)
styles=getSampleStyleSheet();styles['Title'].textColor=colors.HexColor('#006600')
content={
'proposal':('Project Proposal',[('Project topic','CampusFlow: Digital Project Supervision and Progress Tracking'),('Problem','Fragmented email and paper supervision make it difficult to identify outstanding work, review decisions and approaching deadlines.'),('Aim','Build a shared workspace where students and supervisors can manage topics, chapter submissions, revisions, feedback and final approval.'),('Approach','Use role-based authentication, a private document store, five equal chapter milestones and explicit activity-based project health rules.'),('Expected demonstration','A student submits a chapter. The lecturer reviews it, leaves feedback and sets a revision date. The dashboard updates as chapters are approved.')]),
'chapter-1':('Chapter One: Introduction',[('Background','Final-year projects need regular supervision and a clear record of progress. CampusFlow brings the student and assigned lecturer into a shared project workspace.'),('Objectives','Support topic approval, private uploads, version history, chapter review, feedback, extensions and departmental oversight.'),('Scope','This demonstration covers one student, one lecturer and a Computer Science project. The sample content illustrates the application workflow rather than reporting a participant study.')]),
'chapter-2':('Chapter Two: Literature Review',[('Review themes','Digital supervision combines document management, formative feedback, access control and milestone reporting.'),('Design implications','A useful system distinguishes pending work from approved work, preserves previous document versions and makes review outcomes visible to students.'),('Research note','This PDF is demonstration material. It does not present invented citations, survey responses or empirical findings.')]),
'chapter-3':('Chapter Three: Methodology',[('Architecture','The web interface uses Next.js and TypeScript. Firebase provides authentication and structured project records; private Supabase storage holds submission files.'),('Workflow','Topic selection precedes chapter work. Each approved chapter contributes twenty percent. Final approval is a separate supervisor decision after all five chapters are approved.'),('Verification','Functional checks cover role access, topic decisions, submission handling, revision feedback and consistent dashboard updates.')]),
'chapter-4-v1':('Chapter Four: Implementation - First Draft',[('Implemented modules','Student project workspace, lecturer review workspace, topic approval, chapter progress, activity records and notifications.'),('Document lifecycle','An uploaded document starts pending review. The lecturer may request changes or approve it; a revision is stored as another version.'),('Draft revision point','This first draft needs a clearer discussion of how version history and private document access work together. The lecturer requests an update in the demonstration.')]),
'chapter-4-v2':('Chapter Four: Implementation - Revised Draft',[('Revision summary','This revision addresses the lecturer request to explain version history and document permissions.'),('Version history','Each submission records its category, chapter, file name, timestamp and review outcome. Students can revisit earlier files and upload a revised document beside a changes-requested state.'),('Private file access','Viewing and downloading use authenticated server routes. The application checks project membership before issuing a short-lived storage link.'),('Feedback and progress','Written comments and revision dates appear in the student Feedback tab. Only approved chapter stages contribute to the progress percentage.'),('Next step','This revised chapter is ready for lecturer review during the recording.')])}
for name,(title,sections) in content.items():
 story=[Paragraph('CAMPUSFLOW',styles['Title']),Paragraph(title,styles['Heading1']),Paragraph('Demonstration project - sample academic content',styles['Italic']),Spacer(1,18)]
 for heading,text in sections:story.extend([Paragraph(heading,styles['Heading2']),Paragraph(text,styles['BodyText']),Spacer(1,12)])
 SimpleDocTemplate(str(root/(name+'.pdf')),title=title,author='CampusFlow Demo',leftMargin=55,rightMargin=55,topMargin=48,bottomMargin=48).build(story)
print('Prepared six readable demo PDFs.')
